def features(sym,i):
 h=hs[sym];c=h[i-1,3];a=r3.calc_atr(h,i)
 if a is None or a<=0 or not np.isfinite(h[i-168:i,:4]).all() or not np.isfinite(btc[i-13:i,3]).all():return None
 close=h[i-25:i,3];den=np.abs(np.diff(close)).sum()
