def exit_trade(x,mode):
 m=ms[x['symbol']];h=hs[x['symbol']];t=x['entryTs'];k=(t-bt.MS)//M
 if mode=='FIXED24':return r3.calc_trade(x,m,'STOP8_TIME24')
