 ep=float(m[k,0]);best=ep;trail=mode in ('TRAIL48','COMBINED');early=mode in ('EARLY_INVALIDATION','COMBINED');limit=k+288;extended=False
 for j in range(k,min(k+576,len(m)-1)+1):
