   if hi>=stop:reason='HARD_STOP8' if stop>=ep*1.08-1e-9 else ('EARLY_OR_TRAIL_STOP');xp=max(o,stop);et=ts+M
   elif early and ts%H==0 and j-k>=36:
    i=(ts-bt.HS)//H
    if i>=7 and np.isfinite(h[i-7:i,3]).all() and o>ep and h[i-1,3]>h[i-2,3]>h[i-3,3] and h[i-1,3]>np.mean(h[i-7:i-1,3]):reason='INVALIDATION';xp=o;et=ts
   if reason is None:best=min(best,lo);continue
  else:et=ts
  return {**x,'exitTs':et,'entry':ep,'exitPrice':float(xp),'direction':'SHORT','rawReturn':float(1-xp/ep),'exitReason':reason,'mode':mode}
 return None
